package com.harshith.leave.controller; import com.harshith.leave.entity.*; import com.harshith.leave.service.EmployeeService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/employees") public class EmployeeController {private final EmployeeService s; public EmployeeController(EmployeeService s){this.s=s;} @PostMapping public ResponseEntity<Employee> create(@Valid @RequestBody Employee e){return new ResponseEntity<>(s.create(e),HttpStatus.CREATED);} @GetMapping public List<Employee> all(){return s.all();} @GetMapping("/{id}") public Employee get(@PathVariable Long id){return s.get(id);} @PutMapping("/{id}") public Employee update(@PathVariable Long id,@Valid @RequestBody Employee e){return s.update(id,e);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.delete(id);} @GetMapping("/{id}/balance") public LeaveBalance balance(@PathVariable Long id){return s.balance(id);} }